iews", "title": "Reviews", "sources": ["Experience.com", "Google"], "reviews": [{"author": "{reviewer}", "loc": "{city}", "rating": "{review_rating}", "date": "{review_date}", "body": "{review_text}"}]}, {"kind": "disclaimer", "text": "{compliance_disclaimer}"}]}]}$pj$::jsonb,'registry-projection-linted-v1',now())
